//! Conditional formatting against `tests/corpus/xlsx/18_conditional_formatting.xlsx`
//! (generated by `scripts/corpus/gen_features_xlsx.py`): one column per rule
//! type on sheet "Rules", values in rows 2-11. The expectations are what
//! Excel shows for those values.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use sheets_engine::{Conditional, IconShape, Workbook};

const RED_FILL: u32 = 0xFFC7CE;
const RED_FONT: u32 = 0x9C0006;
const GREEN_FILL: u32 = 0xC6EFCE;
const YELLOW_FILL: u32 = 0xFFEB9C;

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/xlsx/18_conditional_formatting.xlsx")
}

fn open() -> Workbook {
    Workbook::open(fixture()).expect("fixture opens")
}

fn col(name: &str) -> u32 {
    name.bytes()
        .fold(0, |acc, b| acc * 26 + u32::from(b - b'A' + 1))
        - 1
}

/// The conditional result of the ten data rows of a column.
fn column(book: &mut Workbook, sheet: u32, name: &str) -> Vec<Option<Arc<Conditional>>> {
    (1..=10)
        .map(|row| book.conditional(sheet, row, col(name)))
        .collect()
}

fn fills(book: &mut Workbook, name: &str) -> Vec<Option<u32>> {
    column(book, 0, name)
        .iter()
        .map(|c| {
            c.as_ref()
                .and_then(|c| c.style.as_ref())
                .and_then(|s| s.fill)
        })
        .collect()
}

/// Rows (0-based within the data) whose fill is `fill`.
fn rows_with(book: &mut Workbook, name: &str, fill: u32) -> Vec<usize> {
    fills(book, name)
        .iter()
        .enumerate()
        .filter(|(_, f)| **f == Some(fill))
        .map(|(i, _)| i)
        .collect()
}

#[test]
fn cell_is_with_priority_and_stop() {
    let mut book = open();
    let cells = column(&mut book, 0, "A");
    let style = |i: usize| cells[i].as_ref().and_then(|c| c.style.clone());
    // 1 is outside 2..9: yellow.
    assert_eq!(style(0).unwrap().fill, Some(YELLOW_FILL));
    assert!(cells[1].is_none());
    for i in 2..=4 {
        assert_eq!(style(i).unwrap().fill, Some(GREEN_FILL), "value {}", i + 1);
    }
    assert!(cells[5].is_none());
    let seven = style(6).unwrap();
    assert!(seven.bold);
    assert_eq!(seven.fill, None);
    // 9 and 10 are > 8 (stop if true): red, and 10 doesn't also get the
    // "not between" yellow.
    for i in 8..=9 {
        let s = style(i).unwrap();
        assert_eq!((s.fill, s.font_color), (Some(RED_FILL), Some(RED_FONT)));
    }
}

#[test]
fn text_rules() {
    let mut book = open();
    assert_eq!(rows_with(&mut book, "B", GREEN_FILL), vec![0, 4, 7]);
    // An empty cell doesn't contain "a" (Excel's ISERROR(SEARCH(..))).
    assert_eq!(rows_with(&mut book, "C", GREEN_FILL), vec![2, 6, 8, 9]);
    assert_eq!(rows_with(&mut book, "D", GREEN_FILL), vec![2]);
    assert_eq!(rows_with(&mut book, "E", GREEN_FILL), vec![9]);
}

#[test]
fn duplicates_top_average() {
    let mut book = open();
    assert_eq!(rows_with(&mut book, "F", RED_FILL), vec![1, 2, 4, 5, 6]);
    assert_eq!(rows_with(&mut book, "G", GREEN_FILL), vec![0, 3, 7, 8, 9]);
    assert_eq!(rows_with(&mut book, "H", GREEN_FILL), vec![7, 8, 9]);
    // Bottom 20 % of ten values: two.
    assert_eq!(rows_with(&mut book, "I", RED_FILL), vec![0, 1]);
    assert_eq!(rows_with(&mut book, "J", GREEN_FILL), vec![5, 6, 7, 8, 9]);
    assert_eq!(rows_with(&mut book, "K", RED_FILL), vec![0, 1, 2, 3, 4]);
}

#[test]
fn blanks_errors_expressions() {
    let mut book = open();
    // A cell holding a space counts as blank (LEN(TRIM(x))=0).
    assert_eq!(rows_with(&mut book, "L", YELLOW_FILL), vec![1, 3, 5, 7]);
    assert_eq!(rows_with(&mut book, "M", RED_FILL), vec![0, 2, 5, 8]);
    // Relative references are shifted from the top-left of the range.
    assert_eq!(rows_with(&mut book, "N", GREEN_FILL), vec![1, 3, 5, 7, 9]);
    assert_eq!(rows_with(&mut book, "O", GREEN_FILL), vec![5, 6, 7, 8, 9]);
}

#[test]
fn colour_scales() {
    let mut book = open();
    let p = fills(&mut book, "P");
    assert_eq!(p[0], Some(0xFFFFFF));
    assert_eq!(p[9], Some(0xFF0000));
    // 50 of 0..90 is 5/9 of the way from white to red.
    assert_eq!(p[5], Some(0xFF7171));
    let q = fills(&mut book, "Q");
    assert_eq!(q[0], Some(0xF8696B));
    assert_eq!(q[9], Some(0x63BE7B));
    let r = fills(&mut book, "R");
    // Numbers 20 (black) to 60 (white); outside, the end colours.
    assert_eq!(&r[..3], &[Some(0), Some(0), Some(0)]);
    assert_eq!(r[4], Some(0x808080));
    assert_eq!(&r[6..], &[Some(0xFFFFFF); 4]);
}

#[test]
fn data_bars() {
    let mut book = open();
    let s = column(&mut book, 0, "S");
    let bar = |i: usize| s[i].as_ref().and_then(|c| c.bar).expect("a bar");
    // -5..4 with automatic bounds: the axis at 5/9.
    let low = bar(0);
    assert!(low.negative);
    assert_eq!(low.color, 0xFF0000);
    assert!((low.axis.unwrap() - 5.0 / 9.0).abs() < 1e-6);
    assert_eq!(low.from, 0.0);
    let zero = bar(5);
    assert!(!zero.negative);
    assert!((zero.to - zero.from).abs() < 1e-6);
    let high = bar(9);
    assert_eq!((high.color, high.to), (0x638EC6, 1.0));
    assert!(!high.gradient);
    let t = column(&mut book, 0, "T");
    let top = t[9].as_ref().and_then(|c| c.bar).unwrap();
    assert!(top.gradient);
    assert_eq!(top.color, 0x63C384);
    assert!(t[9].as_ref().unwrap().show_value);
}

fn icons(book: &mut Workbook, name: &str) -> Vec<(IconShape, u32)> {
    column(book, 0, name)
        .iter()
        .map(|c| {
            let i = c.as_ref().and_then(|c| c.icon).expect("an icon");
            (i.shape, i.color)
        })
        .collect()
}

#[test]
fn icon_sets() {
    let mut book = open();
    let shapes = |v: Vec<(IconShape, u32)>| v.into_iter().map(|i| i.0).collect::<Vec<_>>();
    use IconShape::*;
    assert_eq!(
        shapes(icons(&mut book, "U")),
        [
            ArrowDown, ArrowDown, ArrowDown, ArrowRight, ArrowRight, ArrowRight, ArrowRight,
            ArrowUp, ArrowUp, ArrowUp
        ]
    );
    let lights = icons(&mut book, "V");
    assert!(lights.iter().all(|i| i.0 == Circle));
    assert_eq!(lights[0].1, 0xF8696B);
    assert_eq!(lights[5].1, 0xFFEB84);
    assert_eq!(lights[9].1, 0x63BE7B);
    assert_eq!(
        shapes(icons(&mut book, "W")),
        [
            ArrowDown,
            ArrowDown,
            ArrowDownRight,
            ArrowDownRight,
            ArrowRight,
            ArrowRight,
            ArrowUpRight,
            ArrowUpRight,
            ArrowUp,
            ArrowUp
        ]
    );
    let quarters = shapes(icons(&mut book, "X"));
    assert_eq!(quarters[0], Pie { filled: 0, of: 4 });
    assert_eq!(quarters[9], Pie { filled: 4, of: 4 });
    // Reversed flags: the lowest values get the green flag.
    let flags = icons(&mut book, "Y");
    assert_eq!(flags[0], (Flag, 0x63BE7B));
    assert_eq!(flags[9], (Flag, 0xF8696B));
    // Number thresholds (> 4, >= 8), icon only.
    let z = column(&mut book, 0, "Z");
    let sym: Vec<IconShape> = z
        .iter()
        .map(|c| c.as_ref().unwrap().icon.unwrap().shape)
        .collect();
    assert_eq!(&sym[..4], &[Cross; 4]);
    assert_eq!(&sym[4..7], &[Exclamation; 3]);
    assert_eq!(&sym[7..], &[Check; 3]);
    assert!(!z[0].as_ref().unwrap().show_value);
}

#[test]
fn formats_combine_and_stop() {
    let mut book = open();
    let aa = column(&mut book, 0, "AA");
    for (i, c) in aa.iter().enumerate() {
        let s = c.as_ref().unwrap().style.clone().unwrap();
        if i < 5 {
            assert!(s.bold, "row {i}");
            assert_eq!(s.fill, Some(0xFFFF00));
        } else {
            // > 5 stops: red, without the lower rules' bold and yellow.
            assert!(!s.bold, "row {i}");
            assert_eq!(s.fill, Some(RED_FILL));
        }
    }
    let ab = column(&mut book, 0, "AB");
    for (i, c) in ab.iter().enumerate() {
        let s = c.as_ref().unwrap().style.clone().unwrap();
        assert_eq!(s.fill, Some(0xFFFF00));
        assert_eq!(s.font_color, (i >= 3).then_some(0x0000FF), "row {i}");
    }
}

#[test]
fn number_format_from_rule() {
    let mut book = open();
    let ac = column(&mut book, 0, "AC");
    assert!(ac[4].is_none());
    assert_eq!(
        ac[5].as_ref().unwrap().display.as_ref().unwrap().text,
        "6.00"
    );
}

#[test]
fn time_periods() {
    let mut book = open();
    let days = [0, -1, 1, -3, -40, 40, -6, -7, 0, -2];
    for (i, d) in days.iter().enumerate() {
        book.set_input(0, i as u32 + 1, col("AD"), &format!("=TODAY()+({d})"))
            .unwrap();
    }
    book.recalculate();
    let fills = fills(&mut book, "AD");
    // today, yesterday, tomorrow, -3, -40, +40, -6, -7, today, -2
    let want = [
        Some(GREEN_FILL),
        Some(RED_FILL),
        None,
        Some(GREEN_FILL),
        None,
        None,
        Some(GREEN_FILL),
        None,
        Some(GREEN_FILL),
        Some(GREEN_FILL),
    ];
    assert_eq!(fills, want);
}

#[test]
fn whole_columns_and_absolute_references() {
    let mut book = open();
    let fill = |book: &mut Workbook, r: u32, c: u32| {
        book.conditional(1, r, c)
            .and_then(|c| c.style.clone())
            .and_then(|s| s.fill)
    };
    assert_eq!(fill(&mut book, 14, 0), None);
    assert_eq!(fill(&mut book, 16, 0), Some(RED_FILL));
    // $B1="x": rows 1, 4, 7, ... on both columns.
    assert_eq!(fill(&mut book, 3, 0), Some(YELLOW_FILL));
    assert_eq!(fill(&mut book, 3, 1), Some(YELLOW_FILL));
    assert_eq!(fill(&mut book, 4, 1), None);
    // Row 19 (180): both rules, the whole-column one has priority.
    assert_eq!(fill(&mut book, 18, 0), Some(RED_FILL));
    // Nothing below the data.
    assert_eq!(fill(&mut book, 500, 0), None);
}

#[test]
fn edits_re_evaluate() {
    let mut book = open();
    assert_eq!(rows_with(&mut book, "H", GREEN_FILL), vec![7, 8, 9]);
    // A new largest value pushes 80 out of the top 3.
    book.set_input(0, 1, col("H"), "1000").unwrap();
    assert_eq!(rows_with(&mut book, "H", GREEN_FILL), vec![0, 8, 9]);
    book.undo().unwrap();
    assert_eq!(rows_with(&mut book, "H", GREEN_FILL), vec![7, 8, 9]);
}

#[test]
fn rules_follow_inserted_rows() {
    let mut book = open();
    book.insert_rows(0, 0, 2).unwrap();
    // Column N's "even" rule moved down with its cells.
    let fills: Vec<_> = (3..=12)
        .map(|r| {
            book.conditional(0, r, col("N"))
                .and_then(|c| c.style.clone())
                .and_then(|s| s.fill)
        })
        .collect();
    assert_eq!(fills[1], Some(GREEN_FILL));
    assert_eq!(fills[0], None);
}

fn sheet_xml(path: &Path, part: &str) -> String {
    let mut zip = zip::ZipArchive::new(std::fs::File::open(path).unwrap()).unwrap();
    let mut s = String::new();
    std::io::Read::read_to_string(&mut zip.by_name(part).unwrap(), &mut s).unwrap();
    s
}

/// The `<conditionalFormatting>` elements and the x14 extension, as written.
fn cf_markup(xml: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = xml;
    while let Some(i) = rest.find("<conditionalFormatting ") {
        let end = rest[i..].find("</conditionalFormatting>").unwrap() + i + 24;
        out.push(rest[i..end].to_owned());
        rest = &rest[end..];
    }
    if let Some(i) = xml.find("<x14:conditionalFormattings>") {
        let end = xml.find("</x14:conditionalFormattings>").unwrap();
        out.push(xml[i..end].to_owned());
    }
    out
}

#[test]
fn rules_and_dxfs_survive_save_unchanged() {
    let dir = tempfile::tempdir().unwrap();
    let saved = dir.path().join("saved.xlsx");
    let mut book = open();
    book.set_input(0, 20, 0, "edited").unwrap();
    book.save_as(&saved).unwrap();
    assert!(book.save_notes().is_empty(), "{:?}", book.save_notes());
    for part in ["xl/worksheets/sheet1.xml", "xl/worksheets/sheet2.xml"] {
        assert_eq!(
            cf_markup(&sheet_xml(&fixture(), part)),
            cf_markup(&sheet_xml(&saved, part)),
            "{part}"
        );
    }
    let dxfs = |p: &Path| {
        let s = sheet_xml(p, "xl/styles.xml");
        s[s.find("<dxfs").unwrap()..s.find("</dxfs>").unwrap()].to_owned()
    };
    assert_eq!(dxfs(&fixture()), dxfs(&saved));
    // And the saved file shows the same.
    let mut again = Workbook::open(&saved).unwrap();
    assert_eq!(rows_with(&mut again, "B", GREEN_FILL), vec![0, 4, 7]);
}

#[test]
fn saved_rules_follow_row_and_column_edits() {
    let dir = tempfile::tempdir().unwrap();
    let saved = dir.path().join("moved.xlsx");
    let mut book = open();
    book.insert_rows(0, 0, 2).unwrap();
    book.save_as(&saved).unwrap();
    assert!(book.save_notes().is_empty(), "{:?}", book.save_notes());
    let xml = sheet_xml(&saved, "xl/worksheets/sheet1.xml");
    assert!(xml.contains(r#"<conditionalFormatting sqref="N4:N13">"#));
    assert!(xml.contains("<formula>MOD(N4,2)=0</formula>"));
    assert!(xml.contains("<formula>$A4&gt;N4*0+5</formula>"));
    // The x14 data bar moved too.
    assert!(xml.contains("<xm:sqref>S4:S13</xm:sqref>"));

    // Deleting the first row of a range: the formula is re-based on the new
    // top-left cell (N3 of the original, N2 now).
    let saved = dir.path().join("deleted.xlsx");
    let mut book = open();
    book.delete_rows(0, 1, 1).unwrap();
    book.delete_columns(0, 0, 0).unwrap();
    book.save_as(&saved).unwrap();
    let xml = sheet_xml(&saved, "xl/worksheets/sheet1.xml");
    assert!(
        xml.contains(r#"<conditionalFormatting sqref="M2:M10">"#),
        "{xml}"
    );
    assert!(xml.contains("<formula>MOD(M2,2)=0</formula>"), "{xml}");
    // The rule on column A went with it.
    assert!(!xml.contains(r#"operator="between""#));
    let mut again = Workbook::open(&saved).unwrap();
    // Even values of 2..10 now sit in rows 2, 4, ... (0-based 1, 3, ...).
    let even: Vec<bool> = (1..=9)
        .map(|r| again.conditional(0, r, col("M")).is_some())
        .collect();
    assert_eq!(
        even,
        [true, false, true, false, true, false, true, false, true]
    );
}
